setup() {
  WORKFLOW="${BATS_TEST_DIRNAME}/../.github/workflows/pr-label-assigner.yml"
  PARSER="${BATS_TEST_DIRNAME}/helpers/parse_workflow.py"
  REPO_ROOT="${BATS_TEST_DIRNAME}/.."
}

@test "workflow file exists" {
  [ -f "$WORKFLOW" ]
}

